const want = ($('list_tasks · Webhook').first().json.body || {}).state;
const nodes = (($json.data||{}).viewer||{}).assignedIssues?.nodes || [];
const norm = s => (s||'').toLowerCase();
let tasks = nodes.map(n => ({ id:n.id, ref:n.identifier, title:n.title, priority:n.priority, state:n.state?.name, type:n.state?.type, url:n.url }));
if (want) tasks = tasks.filter(t => norm(t.state) === norm(want) || norm(t.type) === norm(want));
return [{ json: { ok:true, count:tasks.length, tasks } }];

const r = (($json.data||{}).issueUpdate) || {};
if (!r.success) return [{ json: { ok:false, error:'Linear update failed', raw: $json } }];
const i = r.issue || {};
return [{ json: { ok:true, result: `Task updated: ${i.title}`, id:i.id, url:i.url, state:i.state?.name } }];

const b = $('complete_task · Webhook').first().json.body || {};
const target = (b.state || 'Done');
const states = ((($json.data||{}).issue||{}).team||{}).states?.nodes || [];
const norm = s => (s||'').toLowerCase();
let st = states.find(s => norm(s.name) === norm(target));
if (!st && norm(target) === 'done') st = states.find(s => s.type === 'completed');
if (!st) return [{ json: { ok:false, error:`State '${target}' not found for this issue's team.`, available: states.map(s=>s.name) } }];
return [{ json: { id: b.id, stateId: st.id, stateName: st.name } }];

if ($json.ok === false) return [{ json: $json }];
const r = (($json.data||{}).issueUpdate) || {};
if (!r.success) return [{ json: { ok:false, error:'Linear state change failed', raw: $json } }];
const i = r.issue || {};
return [{ json: { ok:true, result: `Task moved to ${i.state?.name}: ${i.title}`, id:i.id, url:i.url, state:i.state?.name } }];
